<?php require_once __DIR__.'/../includes/permissions.php'; require_once __DIR__.'/../includes/csrf.php'; require_login(); require_permission('manage_surveys');
$survey=null;if(isset($_GET['id'])){$s=db()->prepare('SELECT * FROM surveys WHERE id=?');$s->execute([(int)$_GET['id']]);$survey=$s->fetch();if($survey){$q=db()->prepare('SELECT * FROM survey_questions WHERE survey_id=? ORDER BY sort_order,id');$q->execute([$survey['id']]);$survey['questions']=$q->fetchAll();foreach($survey['questions'] as &$question){$o=db()->prepare('SELECT id,option_text,sort_order FROM question_options WHERE question_id=? ORDER BY sort_order,id');$o->execute([$question['id']]);$question['options']=$o->fetchAll();}unset($question);}}
?>
